head.script:
scwin.dbClick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.isIE = function() {
    var myNav = navigator.userAgent.toLowerCase();
    return (myNav.indexOf('msie') != -1) ? parseInt(myNav.split('msie')[1]) : false;
}
scwin.getElementsByClassName = function(name) {
    if (scwin.isIE() == 8) {
        return document.querySelectorAll("." + name);
    } else {
        return document.getElementsByClassName(name.replace(/\./g, " "));
    }
}
scwin.__checkCheckBox = function() {
    if (wq_uuid_3_header__column5_checkboxLabel__id.checked == true) {
        // select all 
        return (WebSquare.wUnit.getDomById('G_'+$p.id+'gridView1___checkbox_col1_0').checked == true) && (WebSquare.wUnit.getDomById('G_'+$p.id+'gridView1___checkbox_col1_1').checked == true) && (WebSquare.wUnit.getDomById('G_'+$p.id+'gridView1___checkbox_col1_2').checked == true);
    } else {
        // un-select all
        return (WebSquare.wUnit.getDomById('G_'+$p.id+'gridView1___checkbox_col1_0').checked == false) && (WebSquare.wUnit.getDomById('G_'+$p.id+'gridView1___checkbox_col1_1').checked == false) && (WebSquare.wUnit.getDomById('G_'+$p.id+'gridView1___checkbox_col1_2').checked == false);
    }
}
scwin.checktype = function() {
    return typeof scwin.getElementsByClassName('w2grid_head_sort_asc')[0] === 'object';
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");	
    WebSquare.wUnit.addCommand("set", "scwin.dbClick('gridView1_column5')");
    //Verify step 3. 선택한 컬럼이 Sort 된다.
    //3. The selected column is sorted.
    WebSquare.wUnit.addCommand("assert", "scwin.checktype()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.getElementsByClassName('w2checkbox_label').length == 4", "true");
    //Test step 4. column5 의 Label 을 클릭한다.
    //4. Click Label in column5
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "scwin.getElementsByClassName('w2checkbox_label')[0].click()");
    //Verify step 4. 체크박스가 전체체크 / 전체해제 된다.
    //4. The check box is checked / unlocked as a whole.    
    WebSquare.wUnit.addCommand("assert", "scwin.__checkCheckBox()", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    //Function 
    //Created by: Quan.Nguyen
